{
    "title": "DNS Guard AI - Dashboards",
    "description": "",
    "inputs": {
        "input_Jpc3C7jh": {
            "options": {
                "defaultValue": "-7d@h,now",
                "token": "global_time"
            },
            "title": "",
            "type": "input.timerange"
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
