    "dataSources": {
        "ds_297CHp3v_ds_c2tunneling_timeline": {
            "name": "dnsguardai_dashboards_recordtype_timelines",
            "options": {
                "query": "| `dns_data` | fields _time, src, query \n| `extract_sub_domain`\n| lookup anomalous_dns_lookup domain OUTPUT anomalous_type\n| where anomalous_type == \"TXT Record Anomalies\" OR anomalous_type == \"HINFO Record Anomalies\" OR anomalous_type == \"AXFR Record Anomalies\" OR anomalous_type == \"ANY Record Anomalies\"\n| timechart count by domain span=4h\n",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_5OsmP7vc_ds_o4JCF8rR": {
            "name": "dnsguardai_dashboards_anomalies_overview_tstats_by_src",
            "options": {
                "query": "| tstats count from datamodel=Network_Resolution by DNS.src",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_9keiG4Qo_ds_c2tunneling_summary": {
            "name": "dnsguardai_dashboards_c2tunneling_affected_source_ip",
            "options": {
                "query": "| `dns_data` | `extract_sub_domain` | `lookup_anomalous_dns(\\\"C2 Tunneling\\\")` | dedup src \n| stats count",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_AkrECVon": {
            "name": "dnsguardai_dashboards_base",
