            "name": "dnsguardai_dashboards_domainshadowing_table",
            "options": {
                "query": "| inputlookup anomalous_dns_lookup\n| where anomalous_type == \"Domain Shadowing\"\n| lookup whitelist_domain_lookup domain OUTPUT domain as whitelisted\n| eval whitelisted = if(isnotnull(whitelisted), \"True\", \"False\")\n| table domain anomalous_type whitelisted\n| rename domain as Domain anomalous_type as \"Anomalous Type\" whitelisted as Whitelisted",
                "queryParameters": {
