            "options": {
                "query": "| `dns_data` | `extract_sub_domain` | where isnotnull(domain) AND subdomain!=\"\" AND isnotnull(subdomain) | stats dc(subdomain) as unique_subdomain by domain\n| sort - unique_subdomain\n| head 10",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
